create extension if not exists pgcrypto;
create table if not exists public.admin_profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null,handle text,role text not null default 'admin',created_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,description text,problem text,solution text,build text,cover_image text,url text,tags text[] not null default '{}',published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.articles(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,excerpt text,content text,cover_image text,tags text[] not null default '{}',medium_url text,published boolean not null default false,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.feed_posts(id uuid primary key default gen_random_uuid(),title text not null,content text,tags text[] not null default '{}',created_at timestamptz not null default now());
create table if not exists public.labs(id uuid primary key default gen_random_uuid(),title text not null,slug text unique,description text,url text,created_at timestamptz not null default now());
create table if not exists public.achievements(id uuid primary key default gen_random_uuid(),title text not null,date text,description text,created_at timestamptz not null default now());
create table if not exists public.pages(id uuid primary key default gen_random_uuid(),title text not null,slug text unique,content text,created_at timestamptz not null default now());
create table if not exists public.contributors(id uuid primary key default gen_random_uuid(),name text not null,slug text unique,bio text,profile_image text,url text,created_at timestamptz not null default now());
create table if not exists public.media(id uuid primary key default gen_random_uuid(),title text,url text,credit text,created_at timestamptz not null default now());
create table if not exists public.handles(id uuid primary key default gen_random_uuid(),platform text not null,label text,url text,created_at timestamptz not null default now());
create table if not exists public.seo_metadata(id uuid primary key default gen_random_uuid(),path text unique not null,title text,description text,og_image text,indexable boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.site_settings(key text primary key,value jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),name text,email text,message text,read boolean not null default false,created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_profiles where id=auth.uid() and role='admin'); $$;
alter table public.admin_profiles enable row level security;alter table public.projects enable row level security;alter table public.articles enable row level security;alter table public.feed_posts enable row level security;alter table public.labs enable row level security;alter table public.achievements enable row level security;alter table public.pages enable row level security;alter table public.contributors enable row level security;alter table public.media enable row level security;alter table public.handles enable row level security;alter table public.seo_metadata enable row level security;alter table public.site_settings enable row level security;alter table public.messages enable row level security;
drop policy if exists admin_profile_self on public.admin_profiles;create policy admin_profile_self on public.admin_profiles for select to authenticated using(id=auth.uid());
drop policy if exists projects_public on public.projects;create policy projects_public on public.projects for select to anon,authenticated using(published=true or public.is_admin());
drop policy if exists projects_admin on public.projects;create policy projects_admin on public.projects for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists articles_public on public.articles;create policy articles_public on public.articles for select to anon,authenticated using(published=true or public.is_admin());
drop policy if exists articles_admin on public.articles;create policy articles_admin on public.articles for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists feed_admin on public.feed_posts;create policy feed_admin on public.feed_posts for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists labs_admin on public.labs;create policy labs_admin on public.labs for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists achievements_admin on public.achievements;create policy achievements_admin on public.achievements for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists pages_admin on public.pages;create policy pages_admin on public.pages for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists contributors_public on public.contributors;create policy contributors_public on public.contributors for select to anon,authenticated using(true);
drop policy if exists contributors_admin on public.contributors;create policy contributors_admin on public.contributors for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists media_admin on public.media;create policy media_admin on public.media for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists handles_public on public.handles;create policy handles_public on public.handles for select to anon,authenticated using(true);
drop policy if exists handles_admin on public.handles;create policy handles_admin on public.handles for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists seo_public on public.seo_metadata;create policy seo_public on public.seo_metadata for select to anon,authenticated using(true);
drop policy if exists seo_admin on public.seo_metadata;create policy seo_admin on public.seo_metadata for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists settings_public on public.site_settings;create policy settings_public on public.site_settings for select to anon,authenticated using(true);
drop policy if exists settings_admin on public.site_settings;create policy settings_admin on public.site_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists messages_insert on public.messages;create policy messages_insert on public.messages for insert to anon,authenticated with check(true);
drop policy if exists messages_admin on public.messages;create policy messages_admin on public.messages for all to authenticated using(public.is_admin()) with check(public.is_admin());
